// ✅ 1234 센트 (정수)

const price = 1234;          // $12.34 를 센트 정수로
const total = price * qty;   // 정수 연산. 오차 0

// 원화는 소수점이 없어 보이지만 방심 금물
//   할인율, 환율, 부가세 계산에서 소수가 끼어든다
//   → 정수(원)로 담되 계산 중 반올림 규칙 관리(2장)
// 큰 금액은 BigInt/Decimal (정수 오버플로 회피)

// 3333 * 3 = 9999   ← 1원이 증발

function split(total, n) {
  const base = Math.floor(total / n);      // 각자 기본 몫
  const rest = total - base * n;           // 남는 원(나머지)
  const shares = new Array(n).fill(base);
  for (let i = 0; i < rest; i++) shares[i] += 1;   // 나머지를 1원씩 분배
  return shares;   // 합 = total (보존!)
}
split(10000, 3);   // [3334, 3333, 3333]. 합 10000
// 나머지를 누구에게: 앞에서부터, 큰 금액 우선, 라운드로빈(규칙으로)

// 값 하나하나 비교(취약) 대신. 합 = 원래 값 불변식으로
test('분배는 합을 보존한다', () => {
  for (let i = 0; i < 100; i++) {          // 무작위 100개
    const total = randInt(1, 100000);
    const n = randInt(2, 13);
    const shares = split(total, n);
    expect(shares.reduce((a, b) => a + b, 0)).toBe(total);   // 합 보존!
  }
});
// 분배, 할인, 세금, 환불 전부 부분의 합 = 전체로 검증
